#include <iostream>
#include <string>
using namespace std;

class Person {
protected:
    string name;
public:
    Person(string n) : name(n) {
        cout << "先搭基类那一半：" << name << endl;
    }
    ~Person() {
        cout << "后拆基类那一半：" << name << endl;
    }
};

class Student : public Person {
public:
    Student(string n) : Person(n) {
        cout << "再初始化子类成员：" << name << endl;
    }
    ~Student() {
        cout << "先执行子类的清理：" << name << endl;
    }
};

int main() {
    string name;
    cin >> name;

    Student k(name);
    cout << "---- 等待执行 ----" << endl;
    return 0;
}

